import { b2cLogin } from '../../services/LoginServices/loginServices';

export const loginUserValidate = async (obj) => {
  let login_res = undefined;
  try {
    const response = await b2cLogin(obj);
    if (response && response.status === 'success') {
      // Payload may be a single object for staff/transport, or an array of
      // student sessions. Normalize to a single session object.
      const payload = response.payload;
      const user =
        Array.isArray(payload) && payload.length > 0 ? payload[0] : payload;
      login_res = { ...response, payload: user };
    } else {
      login_res = response;
    }
  } catch (e) {
    login_res = undefined;
  }
  return Promise.resolve(login_res);
};
